local ADDON_NAME, ns = ...
ns.data = ns.data or {}
ns.data.quests = ns.data.quests or {}

-- English titles, objectives and descriptions transcribed from the installed
-- Forever beta enUS questcache.wdb (client build 1.60.1.70009).
-- The cache has no field labels; only strings with clear quest-text boundaries
-- were mapped here. IDs/titles are guarded by the runtime exact-title check.
-- Two objective lines use server-side $1oa/$2oa counters, which FontString
-- cannot expand. Their Italian wording omits the count; the live tracker keeps it.
local entries = {
    [376] = { "The Damned", "Novice Elreth vuole 6 zampe di razziatore e 6 ali di pipistrello crepuscolare.", "I miei compiti comprendono assistere i guerrieri feriti, confezionare armature e vestiti e aiutare il Sacerdote dell'Ombra Sarvis in tutto ciò di cui ha bisogno.\n\nA giudicare dall'aspetto, anche tu entrerai al suo servizio... dando la caccia ai Senza Mente, se conosco i suoi pensieri. Beh, se vuoi restare tutto intero — e non dubito che tu lo voglia — forse posso aiutarti. Sto finendo le zampe e le ali; portamene un po' e troverò un'armatura per te. Troverai parecchi lupi e pipistrelli a sud." },
    [837] = { "Encroachment", "Uccidi 4 cinghiali Razormane, 4 esploratori Razormane, 4 corridori della polvere Razormane e 4 guardie da battaglia Razormane per Gar'Thok a Collina del Martello.", "Quando arrivammo, i cinghiali Razormane possedevano gran parte di queste terre e ci erano d'intralcio. Con i nostri sforzi ne abbiamo scacciati molti, ma alcuni sono ancora ben trincerati.\n\nÈ durato abbastanza. Per proteggerci, non possiamo permettere ai Razormane di mantenere una presenza nelle nostre terre. I loro accampamenti sono a ovest: cerca i rovi e li troverai. Oggi li scacceremo da Durotar; domani, magari, da tutta Kalimdor." },
    [746] = { "Dwarven Digging", "Raccogli 5 picconi da prospezione.\n\nSpacca i picconi da prospezione presso una fucina per creare attrezzi rotti.\n\nPorta 5 attrezzi rotti a Baine Zoccolo Sanguinario a Villaggio Zoccolo Sanguinario.", "I nani stanno preparando un sito di scavo a nord-ovest. Credono che la terra nasconda segreti, ed è vero, ma scavare e profanare il suolo non è il modo di apprenderne gli insegnamenti.\n\nRaccogli gli attrezzi da scavo dei nani, spaccali e riportami gli attrezzi rotti.\n\nPuoi spaccarli presso una fucina. Ce n'è una a Picco del Tuono, ma va bene qualsiasi fucina, anche quella dell'accampamento dei nani." },
    [784] = { "Vanquish the Betrayers", "Uccidi 10 marinai di Kul Tiras, 8 fanti di marina di Kul Tiras e il Tenente Benedict, poi torna da Gar'Thok a Collina del Martello.", "Guidati dall'Ammiraglio Marefiero, gli umani di Kul Tiras si sono addentrati a Durotar, violando il patto del Capoguerra stretto con Jaina Marefiero per sconfiggere Archimonde anni fa.\n\nL'aggressione umana fu respinta e il Forte di Tiragarde cadde. Ma di recente le riserve dell'Ammiraglio, guidate dal Tenente Benedict, hanno riconquistato il forte e minacciano di nuovo la nostra patria. Questi umani non rispettano la diplomazia.\n\nDimostra il tuo onore e dirigiti a sud, al Forte di Tiragarde, per eliminare gli invasori umani." },
    [806] = { "Dark Storms", "Porta l'artiglio di Fizzle a Orgnil Cicatrice dell'Anima a Collina del Martello.", "Non possiamo permettere alla Lama Ardente di mettere radici a Durotar! Dobbiamo distruggerli prima che il loro male si diffonda!\n\nLe mie indagini hanno scoperto che uno stregone della Lama Ardente, il goblin Fizzle Tempestoscuro, si è accampato nella Gola del Tuono, a nord-ovest. Lui e i suoi accoliti diffondono il caos.\n\nTrova e sconfiggi Fizzle, poi portami il suo artiglio." },
    [808] = { "Minshina's Skull", "Recupera il teschio di Minshina dal cerchio del potere sulle Isole dell'Eco.\n\nPortalo a Maestro Gadrin al Villaggio Sen'jin.", "Nei sogni sento la voce di mio fratello Minshina che mi chiama.\n\nZalazane, lo stregone delle Isole dell'Eco a est, lo ha portato via. Ed è morto.\n\nMa per mio fratello la morte non è libertà. La magia di Zalazane ha imprigionato il suo spirito nel suo stesso teschio. Nei sogni lo vedo insieme ad altri teschi, in un cerchio del potere sull'isola più grande. Finché resterà lì, la sua anima sarà condannata.\n\nTi prego, trova il cerchio e recupera il teschio di Minshina. Portamelo. Liberalo!" },
    [815] = { "Break a Few Eggs", "Porta 3 uova di frustatore a Cuoco Torka a Collina del Martello.", "Bah! Quasi dimenticavo che devo preparare la colazione.\n\n$n, datti una mossa e procurami delle uova di frustatore. Me ne servono almeno tre per il pasto di domani.\n\nI frustatori Zannasangue possono essere feroci e spesso difendono le uova fino alla morte. A volte le seppelliscono troppo a fondo perché sia sicuro dissotterrarle, ma sulle Isole dell'Eco, a sud-est del Villaggio Sen'jin, di solito se ne trovano dappertutto." },
    [817] = { "Practical Prey", "Porta 4 pellicce di tigre di Durotar a Vel'rin Zanna al Villaggio Sen'jin.", "Usiamo molte pelli delle tigri di Durotar, $n. Coperte, armature, tende: abbiamo tanti motivi per cacciare queste bestie e altrettanti per lasciarle prosperare.\n\nÈ ora di sfoltire il branco. La nostra gente cresce e le scorte non bastano più. Mi servono altre pelli per preparare beni adeguati alla nostra tribù.\n\nPortami 4 pellicce di tigre di Durotar e ti ricompenserò. Puoi trovare le tigri sulle isole a sud." },
    [818] = { "A Solvent Spirit", "Porta 4 occhi intatti di makrura e 8 fiale di muco di strisciatore a Maestro Vornal al Villaggio Sen'jin.", "Anche se i miei occhi non vedono bene, la mia vista è ancora abbastanza acuta. Sempre più spesso devo affidarmi alle mie abilità alchemiche per aiutarmi con magie che un tempo mi riuscivano facilmente. Ma non accetto apprendisti: finora non si è fatto avanti nessun troll o orco degno.\n\nTu lo sei? Sì, certo... o almeno credi di esserlo.\n\nMi servono alcune cose. Me le procurerai?\n\nMi occorrono occhi intatti di makrura e fiale di muco di strisciatore. Li trovi sui makrura e sugli strisciatori di Durotar. Ci rivedremo presto." },
    [826] = { "Zalazane", "Sconfiggi Zalazane.\n\nUccidi 8 troll Vudù e 8 troll Stregati.\n\nPorta la testa di Zalazane a Gadrin.", "Lo stregone Zalazane vive sulle Isole dell'Eco, a est: sono le isole che un tempo chiamavamo casa.\n\nDa lì manda i suoi troll sulla terraferma per maledire la nostra gente e assoggettarla.\n\nDeve essere fermato.\n\nSconfiggi Zalazane e i suoi seguaci, un tempo troll Lanciascura e ora perduti. Portami la sua testa e saprò che il suo regno di malvagità è finito." },
    [3093] = { "Rune-Inscribed Note", "Leggi la Nota runica e parla con Meela Albadì a Campo Narache.", "Poco fa un messaggero ti cercava, $n. Credo fosse stata mandata dall'addestratrice degli sciamani Meela. Se la nota viene da lei, non perdere tempo: leggila." },
    [3097] = { "Hallowed Scroll", "Leggi la Pergamena consacrata e parla con il Chierico oscuro Duesten nella chiesa di Albamorta.", "Mentre eri via a occuparti del Flagello senza mente, è arrivata questa pergamena per te. Immagino sia importante, visto che porta il sigillo dell'addestratore dei sacerdoti, Duesten. Ti consiglio di leggerla prima di ripartire." },
    [92422] = { "The Wrath of Rath'mael", "Uccidi Rath'mael nelle Rovine di Lordaeron per Guardia della Morte Kristof a Brill.", "Sono giunte notizie dal Belvedere di Lordamere, nel cuore delle Rovine di Lordaeron. Una nebbia empia ha avvolto le strade e il cimitero, offrendo al Flagello lassù un vantaggio per agire di nascosto.\n\nI nostri esploratori indicano che la nebbia è evocata da una nuova forza tra le loro file: un negromante chiamato Rath'mael. Non possiamo permetterci di aspettare, $n.\n\nSe hai alleati, radunali e porta il loro aiuto ai Reietti. Scaccia questa creatura dalle nostre terre." },
    [92460] = { "Coming of Age", "Parla con Rorian Cercasole nel Bosco di Thendal.", "Ma guarda, hai gli occhi pieni di entusiasmo e sei pronto all'avventura! Aspettavamo il tuo arrivo e il tuo aiuto ci sarà prezioso qui al Villaggio di Thendal. Immagino tu sia pieno di emozione e trepidazione per ciò che ti aspetta. In fondo, si diventa adulti una volta sola.\n\n<Ailee sorride con gentilezza.>\n\nVai a cercare il capo del villaggio, Rorian Cercasole, all'ingresso del grande albero del padre, poco a ovest. Ti affiderà i tuoi primi incarichi." },
    [92461] = { "Harmony in Balance", "Uccidi 8 giovani vuldren nel Bosco di Thendal.", "Viviamo tempi molto incerti. Affrontiamo sfide senza precedenti che potrebbero richiedere soluzioni audaci, ma dobbiamo anche occuparci delle faccende ordinarie del Bosco di Thendal. Per esempio, la recente crescita insostenibile della popolazione di vuldren.\n\nI vuldren sono essenziali per il nostro ecosistema. Gli squilibri, però, vanno corretti per mantenere la delicata armonia condivisa da tutte le creature del bosco.\n\nDirigiti a est e riduci il loro numero." },
    [92462] = { "Infestation Investigation", "Uccidi 8 fastidiose mosche del cirro nel Bosco di Thendal.", "Una delle nostre ranger ha segnalato un'infestazione di mosche del cirro nel Bosco di Thendal.\n\nPossono essere pericolose se lo sciame diventa troppo numeroso. Raggiungi il lato orientale del bosco ed eliminane quante più puoi." },
    [92463] = { "The Cirrusfly Queen", "Uccidi la Regina delle mosche del cirro nel Bosco di Thendal.", "Se la foresta pullula di questi insetti come sembra, uccidere le operaie non basterà.\n\nAddentrati nel bosco e trova la regina. Sarà vicino all'alveare, circondata da soldati più grossi e aggressivi: fai attenzione.\n\nUccidila e torna qui quando hai finito. Ci saremo tolti un problema." },
    [92464] = { "Elemental Unrest", "Parla con Yala Guardavento nel Bosco di Thendal.", "Da quando i nostri benefattori elementali ci hanno lasciati, passiamo da un tumulto all'altro. Ora sono agitate le manifestazioni dei venti vicino alle pietre erette a nord-est.\n\nNon sono davvero coscienti, come gli spiriti del vento senzienti che vivevano qui: questi semplici spiritelli reagiscono alle forze, alle emozioni e alle intenzioni delle creature circostanti.\n\nLa mia apprendista Yala Guardavento è andata a osservarli. Cercala e scopri cosa ha imparato. Approfondisci la questione dei venti agitati." },
    [92465] = { "Agitators", "Uccidi i venti turbolenti e i convertiti Al'Aketh nel Bosco di Thendal.", "Il culto Al'Aketh è una piaga per quest'isola. Questi fanatici adorano il presunto signore elementale di Muro del Cielo, Al'Akir il Signore dei Venti. Sono sicuramente loro ad aver agitato i semplici spiritelli del vento del bosco e ad averli resi violenti.\n\nPurtroppo dovremo disperdere questi venti turbolenti prima che feriscano qualcuno. E dobbiamo mandare al culto un messaggio chiaro: qui non è il benvenuto.\n\nCi darai una mano, $c?" },
    [92469] = { "Return to Rorian", "Riferisci a Rorian Cercasole la presenza degli Al'Aketh nel Bosco di Thendal.", "Hai fatto abbastanza qui, $c. Resterò io a occuparmi degli ultimi rimasti.\n\nTorna al villaggio e informa Rorian della presenza del culto. Non ne sarà felice." },
    [92470] = { "Foul Matriarch", "Uccidi 8 razziatori ursara e raccogli la testa della matriarca della tana, Urs'anah, nel Bosco di Thendal.", "Rorian mi ha detto che ti stavo osservando. Ora ti sottopongo a una prova di determinazione. Ma ti avverto: ti condurrà in grave pericolo.\n\nVai alle caverne a sud. Riduci il numero degli ursara e trova la loro matriarca, quella che le ranger chiamano Urs'anah. Uccidila e portami una prova. Avrai così compiuto un passo importante sul tuo cammino." },
    [92471] = { "Aetheen of the Gales", "Parla con Aetheen delle Burrasche nel Bosco di Thendal.", "Forse non te ne rendi conto, ma tutto ciò che hai fatto è stato una specie di prova, un esame in vista di ciò che ti attende. L'isola è grande e Zephras ha bisogno di giovani avventurieri pieni di energia, se vogliamo superare le sfide che ci aspettano.\n\nAetheen delle Burrasche è una delle guide della nostra gente sull'Isola di Zephras e ti ha tenuto d'occhio. Ha un incarico per te. Parlale per saperne di più." },
    [92472] = { "The Next Step", "Riferisci al Constable Aonda al Villaggio Shen'dar.", "Il culto Al'Aketh è una delle minacce più pervasive dell'Isola di Zephras. Sono fanatici religiosi devoti al presunto signore elementale di Muro del Cielo, Al'Akir il Signore dei Venti. Sono brutali, ostinati e ogni giorno più pericolosi.\n\nIl tuo cammino ti porterà presto al Villaggio Shen'dar, a sud. Quando arrivi, presentati al Constable Aonda. Il culto minaccia Shen'dar e gli abitanti hanno bisogno di aiuto. Digli che ti mando io." },
    [92473] = { "Aggressive Encroachment", "Raccogli 6 artigli di ursara gracile dagli ursara gracili nel Bosco di Thendal.", "La tana degli ursara a sud-ovest sta diventando un problema. La settimana scorsa le ranger hanno dovuto uccidere un ursara adolescente che si era avvicinato al villaggio e aveva aggredito un bambino che giocava vicino ai piedi dell'albero antico, al centro del villaggio.\n\nPer fortuna il bambino è sopravvissuto. La fame e la disperazione rendono queste bestie troppo pericolose per lasciarle indisturbate. Vai a sud e abbatti gli ursara più gracili. Portami i loro artigli come prova." },
    [92474] = { "Falling With Style", "Salta dalla cima della torre di guardia nel Bosco di Thendal e usa l'abilità Camminare sull'Aria per rallentare la caduta.", "Salve, $n! Ti va di fare un gioco?\n\nDevi solo salire sul bordo... e saltare! Usa la tua innata capacità di camminare sull'aria per rallentare la caduta e vedere fin dove riesci a planare.\n\nLe regole sono inventate e i punti non contano, ma ne guadagni di più se atterri proprio davanti a Rorian Cercasole e lo spaventi! Non gli piacerà, ma io mi farò una bella risata se riuscirai a farlo arrabbiare! Ah!" },
    [92517] = { "The Criminal Element", "Uccidi 10 banditi degli Altipiani e il loro capo, «Cattivovento» Bennic, negli Altipiani di Shen'dar.", "C'è una caverna poco più a nord, nascosta dietro una cascata. So bene che un gruppo di banditi la usa come base. Erano un problema già prima dell'arrivo del culto, ma ora sono un vero flagello. Purtroppo non posso sottrarre uomini per occuparmene.\n\nVai lì e sistemali tu. Uccidine quanti più puoi e, se possibile, elimina il loro capo, quello che chiamano «Cattivovento» Bennic. La caverna è pericolosa: fai attenzione." },
    [92532] = { "The Warrior's Path", "Leggi la Nota spiegazzata che ti è stata consegnata, poi cerca Maestro di spada Ren nella torre di guardia del Villaggio di Thendal.", "Mentre eri via, la nostra addestratrice dei guerrieri, Maestro di spada Ren, ha chiesto che ti mandassimo da lei al tuo ritorno. Ti ha lasciato anche questa nota.\n\nLeggila e poi cerca Maestro di spada Ren nella torre di guardia del villaggio." },
    [92544] = { "Al'Aketh Thugs", "Uccidi 6 bruti Al'Aketh, 4 neofiti Al'Aketh e Malduko Spezzanubi nel Bosco di Thendal.", "Una banda di malviventi del culto Al'Aketh si è stabilita vicino alle rovine del tempio, poco a sud-ovest. Li guida un mostro di nome Malduko Spezzanubi. La sacerdotessa suprema Lorthuna, al Santuario di Akir, li avrà mandati per attaccare i viaggiatori e costringere la nostra gente a unirsi al culto.\n\nDevo restare al mio posto per avvertire i viaggiatori che escono dal bosco del pericolo. Ti sarei grato se potessi occuparti dei cultisti e del loro capo." },
    [92551] = { "Stolen Supplies", "Raccogli 10 pacchi di provviste rubate di Shen'dar dal Villaggio Falaath negli Altipiani di Shen'dar.", "Ho sentito che potresti andare al Villaggio Falaath. Quando sarai lì, tieni gli occhi aperti per i nostri depositi di provviste rubati.\n\nDa mesi gli Al'Aketh assaltano le carovane che trasportano cibo, pietre del vento e altre merci tra le pianure e gli altipiani. Danno la colpa ai banditi, ma sappiamo tutti dove finisce la refurtiva. Se a Falaath è rimasto qualcosa, recuperarlo sarebbe di grande aiuto." },
    [92598] = { "The Gift of Skysight", "Usa la tua abilità razziale Vista celeste alla Convergenza elementale nel Bosco di Thendal.", "Come plasmatore del vento, puoi usare la sacra Vista celeste donataci dagli spiriti elementali. Raggiungi le pietre erette a nord-est del villaggio, trova la Convergenza elementale e usa il tuo dono.\n\nPuoi ricorrere alla Vista celeste ovunque, ma il suo beneficio è molto più potente in presenza di una convergenza elementale. Talvolta gli spiriti attratti da questi luoghi di potere ti offriranno anche altre perle di saggezza." },
    [93318] = { "WANTED: Vulgara the Insatiable", "Uccidi Vulgara l'Insaziabile negli Altipiani di Shen'dar e porta la sua testa a Danarii Bellowveil.", "Per ordine del Constable Aonda dei Pacificatori, viene messa una taglia sulla calamità degli Altipiani, Vulgara l'Insaziabile. Avvistata l'ultima volta su una collina poco a sud-ovest del Villaggio Shen'dar, questa terrificante vuldren alata è molto pericolosa: avvicinati con cautela.\n\nConsegna la testa della bestia a Danarii Bellowveil per ricevere la ricompensa." },
    [93552] = { "Harvesting Windstones", "Raccogli 15 ammassi di pietre del vento dalle pietre del vento grezze nel Bosco di Thendal.", "Le pietre del vento sono una risorsa essenziale sull'Isola di Zephras: contengono l'energia grezza e concentrata dei venti. Gli elementali del vento che vivevano qui con noi sono scomparsi secoli fa e, da allora, la magia che sostiene l'isola si affievolisce lentamente. Pur con i loro limiti, le pietre del vento restano una fonte affidabile di energia e hanno un grande valore.\n\nTroverai pietre grezze sparse per il bosco. Mi aiuti a raccoglierle?" },
    [93926] = { "The Western Watch", "Trova il Pacificatore Vaaniel alla torre di guardia occidentale.", "Qualunque sia il motivo per cui il culto ha attaccato la torre, non vale la vita della nostra gente.\n\nVai a sud-ovest e controlla quella torre di guardia. Trova i Pacificatori e di' loro di tornare al villaggio. Difendere la torre non vale le vite che costerebbe; preferisco radunare qui i pochi difensori che abbiamo per proteggere i cittadini.\n\nIl responsabile è il Pacificatore Vaaniel. Digli di tornare qui al più presto. Sbrigati!" },
    [94414] = { "The Anchors of Zephras", "Parla con Halaan Occhio di Falco e prendi in prestito il suo dono per osservare in lontananza il pilone-ancora.", "Salve, giovane $n. Vengo spesso qui per ammirare l'antico pilone-ancora. Dono degli spiriti del vento, questi piloni legano e sostengono la nostra isola. Ultimamente, però, la loro magia è diventata instabile e incostante.\n\nNon vedo segni di sofferenza. Il loro splendore è immutato.\n\nSe vuoi, posso prestarti il mio dono per osservarli." },
    [96101] = { "The Great Outdoors", "Siediti vicino al falò rudimentale di Raan digitando /sit nella chat e attendi di ricevere il beneficio Riposo rinvigorente.", "Salve, $c. Hai l'aria di un avventuriero, e questo è un bene. Il mondo ha bisogno di anime irrequiete come noi, in cerca di fortuna e gloria.\n\nPer avere successo dovrai imparare a cavartela nelle terre selvagge. Non so come te la cavi all'aperto, ma potrei insegnarti qualcosa, se ti interessa.\n\nSiediti accanto al fuoco e mettiti comodo. Ti spiegherò tutto." },
    [96604] = { "The Great Outdoors", "Siediti vicino al falò rudimentale di Brakk digitando /sit nella chat e attendi di ricevere il beneficio Riposo rinvigorente.", "Salve, $c. Hai l'aria di un avventuriero, e questo è un bene. Il mondo ha bisogno di anime irrequiete come noi, in cerca di fortuna e gloria.\n\nPer avere successo dovrai imparare a cavartela nelle terre selvagge. Non so come te la cavi all'aperto, ma potrei insegnarti qualcosa, se ti interessa.\n\nSiediti accanto al fuoco e mettiti comodo. Ti spiegherò tutto." },
    [96638] = { "The Adventurer", "Parla con Raan Selvavento nei pressi del Villaggio Shen'dar.", "Sempre più avventurieri come te cercano gloria e fortuna lontano dalla sicurezza del Bosco di Thendal. Uno di loro ha allestito un accampamento fuori dal Villaggio Shen'dar, lungo la strada che porta a sud-ovest dal bosco.\n\nCercalo e scopri cosa può insegnarti per aiutarti nei tuoi viaggi." },
    [96821] = { "Legging It", "Uccidi 6 rampicanti Ombra della Cresta e 6 predatori Ombra della Cresta nel sud di Durotar, poi riferisci a Gar'thok a Collina del Martello.", "Ultimamente vediamo sempre meno viaggiatori provenienti da Collina del Martello. Gli scorpidi non erano piacevoli, ma ora si dice che dei ragni abbiano fatto il nido lungo la strada.\n\nSe ti capita di andare a nord, uccidine qualcuno lungo il cammino. Poi avvisa Collina del Martello: la strada sarà un po' più sicura." },
    [96822] = { "For Honor", "Raccogli l'ascia da battaglia, l'arco e lo scudo del razziatore nei pressi del Forte di Tiragarde, poi riportali a Turroc a Collina del Martello.", "Abbiamo perso molti valorosi guerrieri dell'Orda durante il saccheggio del Forte di Tiragarde. Ora che gli umani hanno rinforzato le rovine, non riusciamo a recuperare i loro resti per onorarli come si deve.\n\nVai alle rovine intorno al forte e cerca le armi lasciate dai nostri caduti. Le esporremo in un luogo d'onore." },
    [96825] = { "This Fruit Could Bite Back", "Cuoco Torka a Collina del Martello vuole che tu raccolga 8 frutti di fico d'India dai territori dei Razormane a ovest della città.", "I nostri cacciatori e pescatori portano molto cibo gustoso alle truppe, ma raramente riescono a procurare un dolce.\n\nHo visto un cactus che produce frutti spinosi e saporiti. Cresce soltanto sulle colline a ovest, dove i maledetti cinghiali Razormane hanno i loro accampamenti. Superali e portamene qualcuno. Fai attenzione: i frutti sono spinosi quanto i Razormane!" },
    [97223] = { "Bloodtalon Matriarch", "Porta le uova della matriarca Zannasangue a Xar'Ti al Villaggio Sen'jin.", "Ho addestrato personalmente tutti i rapaci che vedi qui. Provengono da ogni parte di Kalimdor, ma alcuni dei migliori sono i rapaci Zannasangue delle isole al largo della costa.\n\nUna di loro, la matriarca Zannasangue, è particolarmente feroce: ha ucciso molti abitanti del villaggio ed è diventata troppo pericolosa per lasciarla vicino ai nostri confini. Se riesci a ucciderla, portami le sue uova: potremo allevare i piccoli come alleati invece che come nemici." },
    [97225] = { "Forgotten Loa Idols", "Raccogli gli idoli loa dimenticati dalle Isole dell'Eco e portali a Maestro Gadrin al Villaggio Sen'jin.", "Quando fuggimmo dalle isole ora abitate da Zalazane e dai suoi simili, lasciammo molti idoli preziosi che ci aiutano a comunicare con gli spiriti che veneriamo: i loa. Sono molto importanti per la nostra tribù.\n\nI seguaci di Zalazane non rispettano i loa e hanno sparso gli idoli sulle isole più grandi.\n\nSe non li raccogliamo, i loa se ne accorgeranno e offenderne uno è una cosa grave.\n\nVai, trova quanti più idoli loa puoi e riportameli." },
    [99156] = { "Rear Guard Patrol", "Porta il cuore di Strappartiglio a Guardia della Morte Linnea.", "Maledizione! Mentre eri di pattuglia è arrivato un nuovo rapporto. È stata avvistata un'abominazione ribelle nelle Terre Infette Orientali, vicino alla Valle di Telaragna.\n\nC'è qualcosa che non va. Le abominazioni non oltrepassano inosservate il Bastione.\n\nLa faccenda deve restare riservata. Quella creatura, però, non cadrà facilmente: ti serviranno alleati, se non vuoi diventare il suo prossimo pasto.\n\nPorta a termine l'incarico e sarai ricompensato. Portami il suo cuore come prova." },
}

