for id, value in pairs(entries) do
    local unpackValues = table.unpack or unpack
    local enTitle, objectives, description = unpackValues(value)
    local quest = ns.data.quests[id]
    if quest and quest.enTitle == enTitle then
        quest.objectives = quest.objectives or objectives
        quest.description = quest.description or description
    elseif not quest then
        ns.data.quests[id] = {
            enTitle = enTitle,
            title = titles[id] or enTitle,
            objectives = objectives,
            description = description,
        }
    end
end
